        uint256 initialBalanceERC20 = IERC20(TARGET).balanceOf(address(this));

        uint256 initialBalanceHoney = honey.balanceOf(attacker);
        uint256 initialTotalSupply = honey.totalSupply();
        uint256 initialCharityTotal = honey.totalCharity();

        // Set attacker as FeeAddress (impersonate owner)
        address owner = honey.owner();
        vm.startPrank(owner);
        honey.setAsCharityAccount(attacker);
        vm.stopPrank();

        // Execute multiple transfers to accumulate charity fees
        uint256 transferAmount = 10000 * 1e18;
        address recipient = address(0x1234);
        vm.label(recipient, "Recipient");

